async function handleMessageEvent(event) {
  const text3 = event.message.text;
  const pageMatch = text3.match(/p=(.*)/);
  let page = pageMatch && pageMatch[1] ? +pageMatch[1] : 1;
  page = isNaN(page) ? 1 : page;
  const id = text3.match(/id=(.*)/)?.[1];
  const videoId = text3.match(/videoId=(.*)/)?.[1];
  switch (true) {
    case text3.includes("@hey"):
    case text3.includes("@heybot"):
      return replyActionList(event);
    case text3.includes("@近期上映電影"):
      return handleMovieList(event, page);
    case text3.includes("@威秀影城近期上映"):
      return handleVieShowComingMovieList(event, page);
    case text3.includes("@Nico排行"):
      return handleNicoRankList(event, page);
    case text3.includes("@Anime1"):
      switch (true) {
        case !!id:
          return handleAnime1BangumiEpisode(event, id);
        case !!videoId:
          return handleAnime1Video(event, videoId);
        default:
          return handleAnime1List(event, page);
      }
    case text3.includes("@Agefans"):
      return handleAgefansList(event, page);
    case text3.includes("@新番實況"):
      return handleKomicaList(event, "live", page);
    case text3.includes("@新番捏他"):
      return handleKomicaList(event, "new", page);
    default:
      break;
  }
}
