// src/middlewares/webhook.middleware.ts
var CHANNEL_SECRET = process.env.LINE_CHANNEL_SECRET;
var lineWebhookMiddlewares = [
  async (c3, next2) => {
    const signature = c3.req.header("X-Line-Signature");
    const body = await c3.req.text();
    if (!signature || !body) {
      return c3.json({ error: "Invalid request" }, 400);
    }
    const hash = crypto4.createHmac("SHA256", CHANNEL_SECRET).update(body).digest("base64");
    if (hash !== signature) {
      return c3.json({ error: "Invalid signature" }, 400);
    }
    c3.set("lineEvents", JSON.parse(body).events);
    await next2();
  },
  async (c3) => {
    const events = c3.get("lineEvents");
    const handleEventPromise = events.map((event) => {
      console.log(event);
      switch (event.type) {
        case "message":
          return handleMessageEvent(event);
      }
      return;
    });
    const result = await Promise.all(handleEventPromise);
    return c3.json(result);
  }
];

