// src/libs/line.lib.ts
var tokenURL = "https://notify-bot.line.me/oauth/token";
var statusURL = "https://notify-api.line.me/api/status";
var handleSubscribe = async (code, redirect_uri) => {
  console.log("code", code);
  console.log("redirect_uri", redirect_uri);
  try {
    const form = new import_form_data2.default;
    form.append("grant_type", "authorization_code");
    form.append("redirect_uri", redirect_uri);
    form.append("client_id", process.env.NOTIFY_CLIENT_ID);
    form.append("client_secret", process.env.NOTIFY_CLIENT_SECRET);
    form.append("code", code);
    const ret = await import_node_fetch3.default(tokenURL, {
      method: "POST",
      body: form
    });
    const json = await ret.json();
    console.log(json);
    if (json.status !== 200) {
      return false;
    }
    const token = json.access_token;
    const status = await getTokenStatus(token);
    await LineChatTokenModel.create({
      name: status?.target ?? "",
      token
    });
    return true;
  } catch (err) {
    console.error(err);
    return false;
  }
};
var getTokenStatus = async (token) => {
  try {
    const ret = await import_node_fetch3.default(statusURL, {
      method: "GET",
      headers: {
        Authorization: `Bearer ${token}`
      }
    });
    const json = await ret.json();
    console.log(json);
    if (json.status !== 200) {
      return;
    }
    return json.status === 200 ? json : null;
  } catch (err) {
    return null;
  }
};
var getUserProfile = async (userId) => {
  const user = await LineProfileModel.findOne({
    userId
  });
  if (!user) {
    throw new Error("User not found");
  }
  return user.toJSON();
};
var createUserProfile = async (profile) => {
  const user = await LineProfileModel.create({
    ...profile
  });
  return user.toJSON();
};

