// src/libs/telegram.lib.ts
var getTelegramApiBase = () => {
  const token = process.env.TELEGRAM_BOT_TOKEN;
  if (!token) {
    throw new Error("TELEGRAM_BOT_TOKEN must be set");
  }
  return `https://api.telegram.org/bot${token}`;
};
var upsertTelegramChat = async (profile) => {
  await TelegramChatModel.updateOne({ chatId: profile.chatId }, {
    $set: {
      username: profile.username ?? "",
      firstName: profile.firstName ?? "",
      lastName: profile.lastName ?? "",
      dateUpdated: new Date
    },
    $setOnInsert: {
      dateCreated: new Date
    }
  }, { upsert: true, setDefaultsOnInsert: true });
};
var getTelegramChatIds = async () => {
  const items = await TelegramChatModel.find({});
  return items.map((item) => item.chatId);
};
var sendTelegramMessageToChat = async (chatId, params) => {
  try {
    const apiBase = getTelegramApiBase();
    const ret = await import_node_fetch4.default(`${apiBase}/sendMessage`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json"
      },
      body: JSON.stringify({
        chat_id: chatId,
        text: params.message,
        parse_mode: params.parseMode,
        disable_web_page_preview: params.disablePreview ?? true
      })
    });
    const json = await ret.json();
    return json.ok === true;
  } catch (err) {
    console.error(err instanceof Error ? err.message : String(err));
    return false;
  }
};
var sendTelegramMessage = async (params) => {
  try {
    const chatIds = await getTelegramChatIds();
    if (!chatIds.length) {
      console.warn("[TELEGRAM] no chat id registered");
      return false;
    }
    const results = await Promise.all(chatIds.map((chatId) => sendTelegramMessageToChat(chatId, params)));
    return results.every((bool) => bool);
  } catch (err) {
    console.error(err instanceof Error ? err.message : String(err));
    return false;
  }
};

// src/libs/youtube.lib.ts
var import_fast_xml_parser2 = __toESM(require_fxp2(), 1);
var xmlParser2 = new import_fast_xml_parser2.XMLParser;
var parseXMLtoData = (xmlStr) => {
  const data2 = xmlParser2.parse(xmlStr);
  const self2 = data2.feed?.link?.find((link) => link.rel === "self")?.href ?? "";
  return {
    entry: data2?.feed?.entry,
    self: self2
  };
};

// src/libs/cwb.lib.ts
var import_fast_xml_parser3 = __toESM(require_fxp2(), 1);
var xmlParser3 = new import_fast_xml_parser3.XMLParser;
var parseCwbXMLtoItems = (xmlStr) => {
  const data2 = xmlParser3.parse(xmlStr);
  return data2?.rss?.channel?.item ?? [];
};

