var subscribe = async (callback, topic) => {
  try {
    const formData = new import_form_data3.default;
    const hub = {
      callback,
      topic,
      verify: "async",
      mode: "subscribe",
      verify_token: "",
      secret: "",
      lease_seconds: ""
    };
    for (const key in hub) {
      formData.append(`hub.${key}`, hub[key]);
    }
    await import_node_fetch5.default(`https://pubsubhubbub.appspot.com/subscribe`, {
      method: "POST",
      body: formData
    });
    return true;
  } catch (err) {
    console.error(err instanceof Error ? err.message : String(err));
    return false;
  }
};
