app2.openapi(listRoute, async (c3) => {
  try {
    const { keyword, mode = "" } = c3.req.valid("query");
    const result = new ResultListGenericVM;
    const key = `agefans-list-${keyword}-${mode}`;
    const cacheItems = lruCache.get(key);
    if (cacheItems) {
      result.items = cacheItems;
    } else {
      if (mode === "update") {
        result.items = await getAnimeUpdate();
      } else {
        result.items = keyword ? await queryAnimeList(keyword) : await getAnimeList();
      }
      lruCache.set(key, result.items);
    }
    result.setResultValue(true, "200" /* success */);
    return c3.json(result);
  } catch (err) {
    throw err;
  }
});
