app2.openapi(videoRoute, async (c3) => {
  const { id, pId, eId } = c3.req.param();
  const key = `agefans-video-${id}-${pId}-${eId}`;
  const cacheVideoUrl = lruCache.get(key);
  const videoUrl = cacheVideoUrl || await getAnimeVideo(id, pId, eId);
  if (videoUrl) {
    lruCache.set(key, videoUrl);
  }
  return c3.redirect(videoUrl);
});
