var import_moment5 = __toESM(require_moment(), 1);
var import_node_fetch6 = __toESM(require_lib14(), 1);
var parseRgb256IntegerColor = (color) => {
  const rgb = parseInt(color, 10);
  const r = rgb >>> 4 & 255;
  const g = rgb >>> 2 & 255;
  const b = rgb >>> 0 & 255;
  return `rgb(${r},${g},${b})`;
};
var getBiliBiliDanmaku = async (id) => {
  const response2 = await import_node_fetch6.default(`https://api.bilibili.com/x/v1/dm/list.so?oid=${id}`);
  const xmlString = await response2.text();
  const $2 = esm_default3.load(xmlString, {
    xmlMode: true
  });
  return $2("d").map((i2, el) => {
    const $d = $2(el);
    const p = $d.attr("p");
    if (!p)
      return null;
    const [time, mode, size, color, create2, bottom2, sender, id2] = p.split(",");
    if (!time || !mode || !size || !color || !create2 || !bottom2 || !sender || !id2)
      return null;
    return {
      id: id2,
      sender,
      text: $d.text(),
      msg: $d.text(),
      time: +time,
      digital_time: import_moment5.default.utc(+time * 1000).format("HH:mm:ss"),
      mode: [null, "rtl", "rtl", "rtl", "bottom", "top"][+mode],
      size: +size,
      color: parseRgb256IntegerColor(color),
      bottom: +bottom2 > 0,
      date: create2,
      date_iso_string: new Date(+create2 * 1000).toISOString()
    };
  }).get().filter(Boolean).sort((a2, b) => a2.time > b.time ? 1 : -1);
};

