var getMovieLog = async () => {
  const COLUMN_MAPPING = {
    "日期": "date",
    "片名": "title",
    "國別": "area",
    "版本": "version",
    "影城": "theater",
    "票價": "price",
    "手續費": "fee",
    "張數": "tickets",
    "折扣": "discount",
    "花費": "cost",
    "備註": "memo"
  };
  try {
    const response2 = await fetchGoogleSheet("1wUt7W8p7c-tlaUCZOI6OwGJODfO-TE7VwPMaBvlv9pQ");
    const data2 = JSON.parse(response2.body);
    let keyArr = [];
    return data2.values.reduce((pre, cur, index2) => {
      if (index2 === 0) {
        keyArr = cur;
        return pre;
      }
      const newObj = {
        id: Buffer.from(cur.join(",")).toString("base64"),
        memo: ""
      };
      cur.forEach((value, index3) => {
        const key = COLUMN_MAPPING[keyArr[index3]] || keyArr[index3];
        switch (key) {
          case "date":
            newObj[key] = import_moment6.default(value, "YYYY/MM/DD HH:mm").toISOString();
            break;
          default:
            newObj[key] = isNaN(+value) || !value ? value : +value;
            break;
        }
      });
      pre.push(newObj);
      return pre;
    }, []);
  } catch (err) {
    console.log(err);
    return [];
  }
};
