app16.openapi(fareRoute, async (c3) => {
  const result = new ResultListGenericVM;
  try {
    const cached = lruCache.get(CACHE_KEYS.fare);
    if (cached) {
      result.items = cached;
    } else {
      result.items = await getFareData();
      if (result.items.length) {
        lruCache.set(CACHE_KEYS.fare, result.items);
      }
    }
    result.setResultValue(true, "200" /* success */);
  } catch (e) {
    result.setResultValue(false, "500" /* error */, e.message);
  }
  return c3.json(result);
});
