var result = import_dotenv.default.config();
var env2 = result.parsed;
console.log(env2);
import_moment_timezone2.default.tz.setDefault("Asia/Taipei");
var isDev = false;

class Application {
  app = null;
  static applicationName = "my-api";
  async start() {
    connectMongoDB();
    this.setRouters();
    await this.startListenPort();
  }
  async setRouters() {
    this.app = new OpenAPIHono;
    this.app.doc("/doc", {
      openapi: "3.0.0",
      info: {
        version: "2.0.0",
        title: "MechakuCha API",
        description: "滅茶苦茶 API"
      },
      servers: [
        {
          url: isDev ? `http://localhost:${process.env.PORT || "3000"}` : "https://mechakucha-api.vercel.app",
          description: "開發環境"
        }
      ]
    });
    this.app.get("/docs", Scalar({
      url: "/doc",
      pageTitle: "MechakuCha API 文檔",
      theme: "purple",
      darkMode: false,
      defaultOpenAllTags: true,
      showSidebar: true,
      layout: "modern",
      searchHotKey: "k",
      metaData: {
        title: "MechakuCha API",
        description: "滅茶苦茶 API",
        ogDescription: "提供滅茶苦茶功能的 REST API",
        ogTitle: "MechakuCha API 文檔",
        ogImage: null,
        twitterCard: "summary_large_image",
        twitterTitle: "MechakuCha API 文檔",
        twitterDescription: "滅茶苦茶 API"
      },
      authentication: {
        preferredSecurityScheme: null
      },
      servers: [
        {
          url: isDev ? `http://localhost:${process.env.PORT || "3000"}` : "https://mechakucha-api.vercel.app",
          description: ""
        },
        {
          url: `http://localhost:${process.env.PORT || "3000"}`,
          description: "本地測試環境"
        },
        {
          url: "https://mechakucha-api.vercel.app",
          description: "正式環境"
        }
      ]
    }));
    this.app.use("/webhook", ...lineWebhookMiddlewares).use("*", async (c3, next2) => {
      c3.header("Access-Control-Allow-Origin", "*");
      c3.header("Access-Control-Allow-Headers", "Origin, X-Requested-With, Content-Type, Accept");
      await next2();
    }).route("/", routes_default);
    this.app.get("/", (c3) => {
      return c3.redirect("/docs");
    });
    this.app.onError(errorHandlerMiddleware);
    return;
  }
  async startListenPort() {
    const port = process.env.PORT || "3000";
    serve({
      fetch: this.app.fetch,
      port: parseInt(port)
    });
    console.info(`${Application.applicationName}`, `port on ${port}`);
    console.info(`\uD83D\uDCD6 API 文檔: http://localhost:${port}/docs`);
    console.info(`\uD83D\uDCCB OpenAPI JSON: http://localhost:${port}/doc`);
    if (!process.env.VERCEL) {
      initSchedule();
    }
  }
}

